// Utility functions for OpenCode hook format conversion
export interface NormalizedHook {
  matcher: string;
  hooks: Array<{
    type: 'command';
    command: string;
  }>;
}

export interface OpenCodeHook {
  command: string | string[];
  environment?: Record<string, string>;
}

/**
 * Convert OpenCode hook format to normalized format
 */
export function convertOpenCodeToNormalized(
  openCodeHooks: Record<string, OpenCodeHook[]>,
): Record<string, NormalizedHook[]> {
  const normalized: Record<string, NormalizedHook[]> = {};

  for (const [hookType, hooks] of Object.entries(openCodeHooks)) {
    normalized[hookType] = hooks.map(hook => ({
      matcher: '*', // OpenCode doesn't use matchers
      hooks: [
        {
          type: 'command',
          command: Array.isArray(hook.command) ? hook.command.join(' ') : hook.command,
        },
      ],
    }));
  }

  return normalized;
}

/**
 * Convert normalized hook format to OpenCode format
 */
export function convertNormalizedToOpenCode(
  normalizedHooks: Record<string, NormalizedHook[]>,
): Record<string, OpenCodeHook[]> {
  const openCode: Record<string, OpenCodeHook[]> = {};

  for (const [hookType, hooks] of Object.entries(normalizedHooks)) {
    openCode[hookType] = hooks.map(hook => {
      const command = hook.hooks?.[0]?.command || '';
      return {
        command: command.includes(' ') ? command.split(' ') : [command],
        environment: {
          AGENT_HOOK_TRACK_ALL_TOOLS: 'true',
        },
      };
    });
  }

  return openCode;
}


